<template>
 <div class="sale-page"><PageHead title="权益包选购"><el-button v-if="returnTo" @click="router.push(returnTo)">返回来源</el-button><el-button @click="newSale">新建自由组合</el-button><el-select :model-value="work.record.id||undefined" placeholder="打开已保存清单" aria-label="已保存清单" @change="loadRecord"><el-option v-for="s in store.data.benefitSalesLists||[]" :key="s.id" :value="s.id" :label="`${s.status==='confirmed'?'已确认':'草稿'} · ${s.updatedAt.slice(0,16)} · ${s.lines.length} 件商品`"/></el-select></PageHead>
 <el-alert v-if="error" :title="error" type="error" :closable="false" data-sale-error/>
 <section v-if="readonly" class="panel" data-confirmed-sale><h2>已确认清单 · 历史只读</h2><p>{{work.record.snapshot?.confirmedAt}} · {{work.record.snapshot?.groupName||'自由组合'}}</p><p>本次使用设备：{{snapshotDevice}}</p><el-table :data="work.record.snapshot?.lines||[]"><el-table-column prop="name" label="商品"/><el-table-column prop="spec" label="实际规格"/><el-table-column prop="quantity" label="数量"/><el-table-column label="单价"><template #default="{row}">{{money(row.unitPriceCents)}}</template></el-table-column><el-table-column label="当时适用依据"><template #default="{row}"><details><summary>{{row.evidence?.length??row.declarations.length}} 条依据</summary><CompatibilityEvidence v-if="row.evidence" :evidence="row.evidence"/><p v-for="d in row.evidence?[]:row.declarations" :key="d.id">{{d.source||d.note||'历史正式适用关系'}} · {{d.verification==='confirmed'?'已核验':'待核验'}}</p></details></template></el-table-column></el-table><h3>合计 {{money(work.record.snapshot?.totalCents??0)}}</h3><el-button @click="copyConfirmed">复制为新草稿并按当前资料核对</el-button></section>
 <template v-else><section class="panel scope"><div class="scope-row"><el-radio-group :model-value="work.record.scope.mode" :disabled="busy" aria-label="选购方式" @change="changeMode(String($event))"><el-radio-button value="free">自由组合</el-radio-button><el-radio-button value="group" :disabled="!store.can('product:type-bundle:read')">按权益包选购</el-radio-button></el-radio-group><template v-if="work.record.scope.mode==='group'"><el-select :model-value="work.record.scope.groupId" :disabled="busy" placeholder="选择启用的权益包" aria-label="选择权益包" @change="selectGroup"><el-option v-for="g in enabledGroups" :key="g.id" :value="g.id" :label="g.name"/></el-select><el-button v-if="work.record.scope.groupId" :disabled="busy" @click="selectGroup(work.record.scope.groupId)">明确采用模板最新类型</el-button></template><el-button v-else :disabled="busy" @click="openTypes">选择分类与参与类型</el-button></div>
 <div class="tags"><span>当前类型范围：</span><el-tag v-for="id in work.record.scope.productTypeIds" :key="id">{{typeName(id)}}</el-tag><span v-if="!work.record.scope.productTypeIds.length">尚未选择</span></div><p v-if="work.record.scope.mode==='group'">{{sourceName}} · 本清单保存独立的类型集合，模板后续修改不会自动覆盖。</p>
 <div class="scope-row"><strong>本次使用设备</strong><el-select :model-value="deviceKey(work.record.scope.device)" filterable clearable :disabled="busy" placeholder="选择实际设备或客户已有型号" aria-label="本次使用设备" @change="selectDevice(String($event||''))"><el-option-group label="实际设备规格"><el-option v-for="s in devices.skus" :key="s.id" :value="`sku:${s.id}`" :label="`${s.name} · ${s.spec}`"/></el-option-group><el-option-group label="客户已有设备型号"><el-option v-for="m in devices.models" :key="m.key" :value="`model:${m.key}`" :label="m.label"/></el-option-group></el-select></div><p class="muted">选择使用设备不会自动加入购买清单；只选型号时不能购买虚构的手机。已有手机只买配件时，无需勾选手机类型。</p><el-alert v-if="query.device&&query.device.status!=='resolved'" :title="query.device.message" type="warning" :closable="false"/></section>
 <div class="shopping"><section class="panel"><el-input v-model="search" clearable placeholder="搜索当前可选商品" aria-label="搜索可选商品"/><el-alert v-if="query.error" :title="query.error" :closable="false" type="info"/><section v-for="g in query.groups" :key="g.id" class="type-group"><h3>{{g.name}} <small>{{g.candidates.length}} 个可选商品</small></h3><p v-if="!g.candidates.length" class="muted">{{g.empty}}</p><p v-else-if="!filtered(g.candidates).length" class="muted">搜索没有匹配结果</p><article v-for="c in filtered(g.candidates)" :key="c.id" class="candidate" :data-sale-candidate="c.id"><div><strong>{{c.name}}</strong><p>{{c.spec||c.code}}</p><small>{{c.note}}</small><el-button v-if="store.can('product:compatibility:read')" link @click="maintain(c.id)">适用资料</el-button><details v-if="c.match?.evidence?.length"><summary>适用依据</summary><CompatibilityEvidence :evidence="c.match.evidence"/></details></div><el-button type="primary" plain :disabled="busy" :data-sale-add="c.id" @click="add(c.id)">{{work.record.scope.device?.kind==='sku'&&work.record.scope.device.skuId===c.id?'加入手机':'添加'}}</el-button></article></section>
 <details v-if="store.can('product:compatibility:update')||store.can('product:compatibility:create')" class="diagnostics"><summary>管理诊断：为什么商品没有出现</summary><div v-for="g in query.groups" :key="g.id"><p v-for="d in g.diagnostics" :key="d.id">{{d.name}}：{{d.reason}} <el-button link @click="maintain(d.id)">查看适用资料</el-button></p></div></details></section>
 <section class="panel cart"><h2>本次购买清单</h2><p class="muted">未报价与免费分别记录；金额按分计算。</p><el-empty v-if="!work.record.lines.length" description="尚未添加商品"/><article v-for="l in work.record.lines" :key="l.skuId" class="line" :data-sale-line="l.skuId"><strong>{{saleLabel(store.data,l.skuId).name}}</strong><p>{{saleLabel(store.data,l.skuId).spec}}</p><el-alert v-if="lineIssues.find(i=>i.skuId===l.skuId)" :title="lineIssues.find(i=>i.skuId===l.skuId)!.reason" type="warning" :closable="false"/><div class="line-inputs"><label>数量<el-input-number v-model="l.quantity" :min="1" :max="100000" :precision="0" :disabled="busy" :aria-label="`数量 ${l.skuId}`"/></label><label>本次单价（元）<el-input v-model="work.prices[l.skuId]" placeholder="未报价" :disabled="busy" :aria-label="`报价 ${l.skuId}`"/></label></div><p>行金额：{{lineAmount(l)}} <el-button link type="danger" :disabled="busy" @click="remove(l.skuId)">移除</el-button></p></article><h3>{{amount.complete?'合计':'已报价小计'}}：{{money(amount.cents)}}</h3><p v-if="!amount.complete">还有未报价商品</p><el-button :disabled="busy||!canSave" :loading="busy" data-save-sale @click="save('draft')">保存草稿</el-button><el-button type="primary" :disabled="busy||!canSave||!store.can('product:bundle-sale:confirm')" data-confirm-sale @click="save('confirmed')">确认清单</el-button></section></div></template>
 <el-dialog v-model="typesOpen" title="本次参与的产品类型" width="min(900px,95vw)" :close-on-click-modal="false"><el-select v-model="pendingScope.categoryId" filterable placeholder="选择分类" aria-label="自由组合分类"><el-option v-for="c in store.data.categories" :key="c.id" :value="c.id" :label="categoryPathLabel(store.data.categories,c.id)"/></el-select><TypeSetPicker v-model="pendingScope.productTypeIds" :data="store.data" :category-id="pendingScope.categoryId"/><template #footer><el-button @click="typesOpen=false">取消</el-button><el-button type="primary" :disabled="busy" data-apply-types @click="applyTypes">应用本次类型</el-button></template></el-dialog>
 </div>
</template>
<script setup lang="ts">
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import CompatibilityEvidence from '../components/compatibility/CompatibilityEvidence.vue'
import PageHead from '../components/PageHead.vue'
import TypeSetPicker from '../components/benefit-sales/TypeSetPicker.vue'
import {workingSales,emptySale,emptyScope,type WorkingSale} from '../components/benefit-sales/working'
import {useCatalogStore} from '../stores/catalog'
import {saleQuery,saleLabel,deviceOptions,deviceKey,deviceFromKey,typesProblem} from '../domain/benefitSales/query'
import {copy,priceCents,total} from '../domain/benefitSales/commands'
import type {SaleScope,SaleLine,BenefitSale} from '../domain/benefitSales/types'
import {categoryPathLabel} from '../domain/categoryTree'
import {compatibilityReturnLocation} from '../domain/compatibilityNavigation'
const store=useCatalogStore(),route=useRoute(),router=useRouter(),actor=computed(()=>`${store.activeUserId}:${store.previewUserId}`)
const work=ref<WorkingSale>(copy(workingSales.get(actor.value)||emptySale())),error=ref(''),busy=ref(false),search=ref(''),typesOpen=ref(false),pendingScope=ref(emptyScope())
let internal=false,leavingForMaintenance=false
const stamp=()=>JSON.stringify([work.value.record,work.value.prices]),dirty=()=>work.value.saved!==stamp()&&work.value.record.status!=='confirmed'&&(work.value.record.lines.length>0||work.value.record.scope.productTypeIds.length>0)
const readonly=computed(()=>work.value.record.status==='confirmed'),returnTo=computed(()=>compatibilityReturnLocation(route.query.returnTo)),enabledGroups=computed(()=>(store.data.benefitTypeGroups||[]).filter(g=>g.enabled)),devices=computed(()=>deviceOptions(store.data))
const sourceName=computed(()=>store.data.benefitTypeGroups?.find(g=>g.id===work.value.record.scope.groupId)?.name||'原权益包已停用或不可查看')
const query=computed(()=>saleQuery(store.data,work.value.record.scope)),lineIssues=computed(()=>work.value.record.lines.filter(l=>!query.value.candidates.some(c=>c.id===l.skuId)).map(l=>({skuId:l.skuId,reason:query.value.groups.flatMap(g=>g.diagnostics).find(d=>d.id===l.skuId)?.reason||'不在当前类型范围内'})))
const pricedLines=computed(()=>work.value.record.lines.map(l=>({...l,unitPriceCents:priceCents(work.value.prices[l.skuId]||'')??null}))),amount=computed(()=>total(pricedLines.value)),canSave=computed(()=>store.can(`product:bundle-sale:${work.value.record.id?'update':'create'}`))
const snapshotDevice=computed(()=>work.value.record.snapshot?.device?.host?.steps.map(s=>s.valueId).join(' · ')||'独立购买，无配套设备')
const money=(n:number|null)=>n===null?'未报价':`¥${(n/100).toFixed(2)}`,typeName=(id:string)=>store.data.productTypes.find(t=>t.id===id)?.name||'类型已失效'
function filtered<T extends {name:string;spec:string;code:string}>(rows:T[]){const s=search.value.trim().toLowerCase();return rows.filter(r=>`${r.name} ${r.spec} ${r.code}`.toLowerCase().includes(s))}
function lineAmount(l:SaleLine){const n=priceCents(work.value.prices[l.skuId]||'');return n===undefined?'报价无效':n===null?'未报价':money(n*l.quantity)}
function remove(id:string){work.value.record.lines=work.value.record.lines.filter(l=>l.skuId!==id);delete work.value.prices[id]}
function add(id:string){if(busy.value||readonly.value)return;const latest=saleQuery(store.data,work.value.record.scope);if(!latest.candidates.some(c=>c.id===id)){error.value='商品资料已变化，请核对当前候选';return}const line=work.value.record.lines.find(l=>l.skuId===id);if(line){if(line.quantity<100000)line.quantity++}else{work.value.record.lines.push({skuId:id,quantity:1,unitPriceCents:null});work.value.prices[id]=''}}
async function syncUrl(){internal=true;try{await router.replace({path:route.path,query:{...route.query,group:work.value.record.scope.mode==='group'?work.value.record.scope.groupId:undefined,device:deviceKey(work.value.record.scope.device)||undefined,sale:work.value.record.id||undefined}})}finally{internal=false}}
async function switchScope(next:SaleScope,updateUrl=true){if(busy.value)return false;busy.value=true;try{const fresh=saleQuery(store.data,next),keep=new Set(fresh.candidates.map(c=>c.id)),removed=work.value.record.lines.filter(l=>!keep.has(l.skuId));if(removed.length){await ElMessageBox.confirm(removed.map(l=>`${saleLabel(store.data,l.skuId).name}：${fresh.groups.flatMap(g=>g.diagnostics).find(d=>d.id===l.skuId)?.reason||'超出新类型范围，将移除'}`).join('；'),'切换影响确认',{confirmButtonText:'应用切换并移除',cancelButtonText:'取消，保留原内容',closeOnClickModal:false})}work.value.record.scope=copy(next);for(const l of removed)remove(l.skuId);if(updateUrl)await syncUrl();error.value='';return true}catch(e){if(e!=='cancel'&&e!=='close')error.value=String(e);return false}finally{busy.value=false}}
async function changeMode(mode:string){await switchScope({...copy(work.value.record.scope),mode:mode==='group'?'group':'free',groupId:undefined,productTypeIds:mode==='group'?[]:work.value.record.scope.productTypeIds})}
async function selectGroup(id:string){const g=enabledGroups.value.find(g=>g.id===id);if(!g){error.value='权益包已停用或不存在';return}await switchScope({...copy(work.value.record.scope),mode:'group',groupId:g.id,categoryId:g.categoryId,productTypeIds:[...g.productTypeIds]})}
async function selectDevice(key:string){await switchScope({...copy(work.value.record.scope),device:deviceFromKey(key)})}
function openTypes(){pendingScope.value=copy(work.value.record.scope);typesOpen.value=true}
async function applyTypes(){const problem=typesProblem(store.data,pendingScope.value.productTypeIds);if(problem){error.value=problem;return}if(await switchScope(pendingScope.value))typesOpen.value=false}
async function discard(){if(!dirty())return true;try{await ElMessageBox.confirm('当前清单尚有未保存修改，确定切换？','保留或放弃修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
function setRecord(record:BenefitSale){work.value={record:copy(record),prices:Object.fromEntries(record.lines.map(l=>[l.skuId,l.unitPriceCents===null?'':(l.unitPriceCents/100).toFixed(2)])),saved:''};work.value.saved=stamp();error.value=''}
async function loadRecord(id:string){if(busy.value||!await discard())return;const record=store.data.benefitSalesLists?.find(s=>s.id===id);if(!record){error.value='清单不存在或不可查看';return}setRecord(record);await syncUrl()}
async function newSale(){if(busy.value||!await discard())return;work.value=emptySale();error.value='';await syncUrl()}
async function copyConfirmed(){const old=copy(work.value.record);const q=saleQuery(store.data,old.scope),allowed=new Set(q.candidates.map(c=>c.id));setRecord({...old,id:'',revision:0,status:'draft',snapshot:undefined,createdAt:'',updatedAt:'',lines:old.lines.filter(l=>allowed.has(l.skuId))});work.value.saved='';error.value=old.lines.some(l=>!allowed.has(l.skuId))?'已按当前资料核对，不再合法的商品未复制；历史清单保持不变':'';await syncUrl()}
async function save(status:'draft'|'confirmed'){if(busy.value)return;for(const l of work.value.record.lines)if(priceCents(work.value.prices[l.skuId]||'')===undefined){error.value='报价须为非负金额，最多两位小数';return}busy.value=true;error.value='';const before=stamp();try{const result=await store.saveBundleSale({...copy(work.value.record),lines:pricedLines.value,status},work.value.record.revision,()=>stamp()===before);if(!result.ok){error.value=result.message||'保存失败';return}if('record' in result){setRecord(result.record);await syncUrl();ElMessage.success(status==='confirmed'?'清单已确认':'草稿已保存')}}catch(e){error.value=String(e)}finally{busy.value=false}}
async function maintain(id:string){leavingForMaintenance=true;try{await router.push({path:'/compatibility',query:{tab:'ranges',targetId:id,device:work.value.record.scope.device?.kind==='sku'?work.value.record.scope.device.skuId:undefined,deviceModel:work.value.record.scope.device?.kind==='model'?work.value.record.scope.device.key:undefined,returnTo:route.fullPath}})}finally{leavingForMaintenance=false}}
watch(work,()=>workingSales.set(actor.value,copy(work.value)),{deep:true,flush:'sync'})
watch(actor,()=>{work.value=copy(workingSales.get(actor.value)||emptySale());typesOpen.value=false;error.value='身份已切换，已恢复该身份的独立工作清单'})
onBeforeRouteLeave(async()=>!busy.value&&(leavingForMaintenance||await discard()))
onBeforeRouteUpdate(async to=>{if(internal)return true;if(busy.value)return false;if(to.query.sale&&to.query.sale!==route.query.sale){if(!await discard())return false;const s=store.data.benefitSalesLists?.find(s=>s.id===to.query.sale);if(!s)return false;setRecord(s);return true}const next=copy(work.value.record.scope);if(to.query.group!==route.query.group){const g=enabledGroups.value.find(g=>g.id===to.query.group);if(to.query.group&&!g)return false;next.mode=g?'group':'free';next.groupId=g?.id;if(g){next.productTypeIds=[...g.productTypeIds];next.categoryId=g.categoryId}}if(to.query.device!==route.query.device)next.device=deviceFromKey(String(to.query.device||''));return switchScope(next,false)})
function beforeUnload(e:BeforeUnloadEvent){if(dirty()){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
// Explicit saved record takes precedence; retained work keeps quotes during compatibility navigation.
const saved=store.data.benefitSalesLists?.find(s=>s.id===route.query.sale)
if(saved&&(!workingSales.has(actor.value)||work.value.record.id!==saved.id))setRecord(saved)
else if(!workingSales.has(actor.value)){
 const group=enabledGroups.value.find(g=>g.id===route.query.group);if(group)work.value.record.scope={...emptyScope(),mode:'group',groupId:group.id,categoryId:group.categoryId,productTypeIds:[...group.productTypeIds]}
 if(route.query.device)work.value.record.scope.device=deviceFromKey(String(route.query.device).startsWith('sku:')||String(route.query.device).startsWith('model:')?String(route.query.device):`sku:${route.query.device}`)
 if(!work.value.record.scope.device&&route.query.model&&route.query.version){const version=store.data.specModelVersions.find(v=>v.templateId===route.query.model&&v.id===route.query.version),node=version?.nodesSnapshot.find(n=>n.id===route.query.node),options=devices.value.models.filter(m=>m.host.productModelId===route.query.model&&m.versionIds.includes(String(route.query.version))&&(!route.query.node||node?.nodeType==='VALUE'&&m.host.steps.some(s=>s.valueId===node.valueId&&s.attributeId===node.attributeId)));if(options.length===1)work.value.record.scope.device={kind:'model',key:options[0]!.key}}
}
// A fresh explicit entrance must never silently retain a different device/template from earlier work.
onMounted(async()=>{
 if(route.query.sale)return
 const next=copy(work.value.record.scope);let changed=false
 if(typeof route.query.group==='string'&&route.query.group!==next.groupId){const g=enabledGroups.value.find(g=>g.id===route.query.group);if(g){Object.assign(next,{mode:'group',groupId:g.id,categoryId:g.categoryId,productTypeIds:[...g.productTypeIds]});changed=true}else error.value='指定权益包已停用或不存在，请选择其他包或自由组合'}
 if(typeof route.query.device==='string'){const key=route.query.device.startsWith('sku:')||route.query.device.startsWith('model:')?route.query.device:`sku:${route.query.device}`;if(key!==deviceKey(next.device)){next.device=deviceFromKey(key);changed=true}}
 if(changed){if(readonly.value){work.value=emptySale();work.value.record.scope=next;await syncUrl()}else if(!await switchScope(next))await syncUrl()}
})

</script>
<style scoped>.panel{padding:18px;margin-bottom:16px}.scope-row,.tags{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:8px 0}.scope-row .el-select{min-width:280px;max-width:650px;flex:1}.shopping{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(350px,1fr);gap:16px}.candidate{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0;border-bottom:1px solid var(--el-border-color-lighter)}p{margin:8px 0;line-height:1.6}.muted,small{color:var(--el-text-color-secondary)}.line{padding:14px 0;border-bottom:1px solid var(--el-border-color)}.line-inputs{display:flex;gap:12px}.line-inputs label{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}.line-inputs .el-input-number{width:100%}.diagnostics{margin-top:20px}.type-group h3{margin:20px 0 4px}.tags{padding:10px 0}@media(max-width:950px){.shopping{grid-template-columns:1fr}.scope-row .el-select{min-width:220px}}</style>
